     1	import React from 'react';
     2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
     3	import { ZimmInputAction } from 'app/components/ui-kits/molecules/zimmInputAction';
     4	import { ZimmSubscribeModal } from 'app/components/ui-kits/organisms/zimmSubscribeModal';
     5	import { useSubscribeSection } from 'app/hooks/useSubscribeSection';
     6	import { useUiCopy } from 'app/hooks/useUiCopy';
     7	
     8	const ZIMM_SUBSCRIBE_SECTION_RECIPE = 'ZimmSubscribeSection';
     9	
    10	// English fallbacks for useUiCopy() below — not props. Kept as named constants (rather than
    11	// inline literals at each t() call) since these are full sentences, not single words.
    12	const SUBSCRIBE_SUCCESS_MESSAGE = "You're on the list! Be the first to know about new collections and new arrivals.";
    13	const SUBSCRIBE_UNAVAILABLE_MESSAGE = 'Subscription is temporarily unavailable. Please try again later.';
    14	
    15	type ZimmSubscribeSectionProps = {
    16	  heading: string;
    17	  body: string;
    18	  /** Forces the post-submit success state. For Storybook/tests only. */
    19	  initialSubscribed?: boolean;
    20	  privacyPolicyHref: string;
    21	  /**
    22	   * Opt in to the HPC-035 first/last-name capture modal. Defaults to false: SFCC-55 ships this
    23	   * section as an input plus submit button only, and the modal has no design yet.
    24	   */
    25	  enableNameCapture?: boolean;
    26	};
    27	
    28	/**
    29	 * Newsletter sign-up organism — email capture, the idle/unavailable/success/error state
    30	 * machine (owned by useSubscribeSection), and the optional HPC-035 name-capture modal. Extracted
    31	 * from the footer so it can be placed on any page, not just the global footer.
    32	 *
    33	 * Microcopy (labels, button text, status messages) comes from useUiCopy(), not props — it's
    34	 * app-wide static content, sourced the same way any component reads translated strings via
    35	 * useIntl(), and falls back to the English literals here with no UiCopyProvider mounted
    36	 * (Storybook, this component's own tests).
    37	 *
    38	 * @param props see ZimmSubscribeSectionProps
    39	 */
    40	export const ZimmSubscribeSection = ({
    41	  heading,
    42	  body,
    43	  initialSubscribed = false,
    44	  privacyPolicyHref,
    45	  enableNameCapture = false,
    46	}: ZimmSubscribeSectionProps) => {
    47	  const { submitState, modalOpen, closeModal, handleEmailSubmit, handleModalSubmit } = useSubscribeSection({
    48	    initialSubscribed,
    49	    enableNameCapture,
    50	  });
    51	  const styles = useMultiStyleConfig(ZIMM_SUBSCRIBE_SECTION_RECIPE, {});
    52	  const { t } = useUiCopy();
    53	  const emailLabel = t('footer.subscribe.emailLabel', 'Email');
    54	  const subscribeButtonLabel = t('footer.subscribe.buttonLabel', 'Subscribe');
    55	  const successMessage = t('footer.subscribe.successMessage', SUBSCRIBE_SUCCESS_MESSAGE);
    56	  const unavailableMessage = t('footer.subscribe.unavailableMessage', SUBSCRIBE_UNAVAILABLE_MESSAGE);
    57	
    58	  return (
    59	    <div>
    60	      <chakra.p __css={styles.heading}>{heading}</chakra.p>
    61	      <chakra.p __css={styles.body}>{body}</chakra.p>
    62	      <chakra.div aria-live="polite" __css={styles.control}>
    63	        {submitState === 'idle' && (
    64	          <ZimmInputAction
    65	            label={emailLabel}
    66	            type="email"
    67	            name="footer-email"
    68	            icon="chevron-right"
    69	            buttonLabel={subscribeButtonLabel}
    70	            inverse
    71	            onSubmit={handleEmailSubmit}
    72	          />
    73	        )}
    74	        {submitState === 'success' && <chakra.p __css={styles.success}>{successMessage}</chakra.p>}
    75	        {(submitState === 'unavailable' || submitState === 'error') && (
    76	          <chakra.p role="alert" __css={styles.error}>
    77	            {unavailableMessage}
    78	          </chakra.p>
    79	        )}
    80	      </chakra.div>
    81	
    82	      {enableNameCapture && (
    83	        <ZimmSubscribeModal
    84	          isOpen={modalOpen}
    85	          onClose={closeModal}
    86	          onSubmit={handleModalSubmit}
    87	          privacyPolicyHref={privacyPolicyHref}
    88	        />
    89	      )}
    90	    </div>
    91	  );
    92	};

########## hooks/useSubscribeSection.ts ##########
     1	import { useRef, useState } from 'react';
     2	
     3	// 'unavailable' shown until HPC-036 (Omneo) lands; prevents false "You're on the list!" feedback.
     4	// 'success'/'error' set only after a confirmed/failed Omneo response (post HPC-036).
     5	export type SubmitState = 'idle' | 'unavailable' | 'success' | 'error';
     6	
     7	// The HPC-036 sign-up payload: footer email (HPC-034) + modal names (HPC-035).
     8	// Assembled across two steps, POSTed to Omneo → Emarsys when the integration lands.
     9	type PendingSignup = { email: string; firstName: string; lastName: string };
    10	
    11	type UseSubscribeSectionParams = {
    12	  /** Forces the post-submit success state up front. For Storybook/tests only. */
    13	  initialSubscribed?: boolean;
    14	  /** Opt in to the HPC-035 name-capture modal instead of the placeholder path. */
    15	  enableNameCapture?: boolean;
    16	};
    17	
    18	type UseSubscribeSectionReturn = {
    19	  submitState: SubmitState;
    20	  modalOpen: boolean;
    21	  closeModal: () => void;
    22	  handleEmailSubmit: (email: string) => void;
    23	  handleModalSubmit: (firstName: string, lastName: string) => void;
    24	};
    25	
    26	/**
    27	 * State machine for the subscribe section: the idle/unavailable/success/error submit states,
    28	 * the optional HPC-035 name-capture modal, and the pending-signup payload assembled across both
    29	 * steps.
    30	 *
    31	 * Extracted from ZimmSubscribeSection per components.md's extract-to-hook threshold (≥2 related
    32	 * useState that change together — submitState and modalOpen here, plus the pendingSignupRef).
    33	 *
    34	 * @param params initialSubscribed (Storybook/test only) and enableNameCapture (HPC-035 opt-in)
    35	 * @returns current submit/modal state plus the two submit handlers
    36	 */
    37	export const useSubscribeSection = ({
    38	  initialSubscribed = false,
    39	  enableNameCapture = false,
    40	}: UseSubscribeSectionParams): UseSubscribeSectionReturn => {
    41	  // Map the Storybook-only `initialSubscribed` flag to the success state.
    42	  // Post HPC-036, 'success' will only be reached via a confirmed Omneo response.
    43	  const [submitState, setSubmitState] = useState<SubmitState>(initialSubscribed ? 'success' : 'idle');
    44	  // Ref, not state: nothing renders from it, so a re-render on capture would be wasted. The
    45	  // footer input unmounts once submitState leaves 'idle', so the email must be captured here at
    46	  // step 1 or it is unrecoverable at step 2.
    47	  const pendingSignupRef = useRef<PendingSignup>({ email: '', firstName: '', lastName: '' });
    48	  const [modalOpen, setModalOpen] = useState(false);
    49	
    50	  const handleEmailSubmit = (email: string) => {
    51	    pendingSignupRef.current.email = email;
    52	    if (enableNameCapture) {
    53	      setModalOpen(true);
    54	      return;
    55	    }
    56	    // Descoped path, and the default. SFCC-55's AC scopes this section to "an email input field
    57	    // and submit button as a placeholder component" and defers the Omneo sign-up to a separate
    58	    // story. The name-capture modal is HPC-035/HPC-037 but has no Figma node — all nine of its
    59	    // theme parts are undesigned. So it does not ship enabled: submitting a valid email goes
    60	    // straight to the placeholder message. Flip enableNameCapture on once Kiera supplies the
    61	    // design and HPC-035 is scheduled; the modal and its coverage are already built and tested.
    62	    setSubmitState('unavailable');
    63	    pendingSignupRef.current = { email: '', firstName: '', lastName: '' };
    64	  };
    65	
    66	  const handleModalSubmit = (firstName: string, lastName: string) => {
    67	    pendingSignupRef.current = { ...pendingSignupRef.current, firstName, lastName };
    68	    // PLACEHOLDER until HPC-036 (Omneo integration) lands: POST pendingSignupRef.current here.
    69	    // On confirmed response → setSubmitState('success'). On failure → setSubmitState('error').
    70	    // 'unavailable' is shown until the integration is live; never show false success.
    71	    setModalOpen(false);
    72	    setSubmitState('unavailable');
    73	    // Nothing was sent, so nothing needs retaining — the record holds customer PII and there is
    74	    // no request for it to outlive. When HPC-036 adds the POST above, this reset stays; it just
    75	    // moves to after a confirmed response. React memory only, never storage, never logged.
    76	    pendingSignupRef.current = { email: '', firstName: '', lastName: '' };
    77	  };
    78	
    79	  return {
    80	    submitState,
    81	    modalOpen,
    82	    // A Cancel (as opposed to a submit) is still an exit path for the captured email, so it
    83	    // gets the same clear as handleModalSubmit — a shopper who backs out shouldn't leave PII
    84	    // sitting in memory waiting for a signup that never completes.
    85	    closeModal: () => {
    86	      setModalOpen(false);
    87	      pendingSignupRef.current = { email: '', firstName: '', lastName: '' };
    88	    },
    89	    handleEmailSubmit,
    90	    handleModalSubmit,
    91	  };
    92	};

