    75	  });
    76	
    77	  test('no override-component style uses a bare token key on a registered scale', () => {
    78	    const offenders = collect()
    79	      .filter(
    80	        (f) =>
    81	          (SPACE_PROPS.has(f.prop) && SPACING_KEYS.includes(f.value)) || (COLOR_PROPS.has(f.prop) && COLOR_KEYS.has(f.value)),
    82	      )
    83	      .map(where);
    84	
    85	    // Not a wrong-value bug — space and colors ARE registered Chakra scales, so `gap: 'xs'` and
    86	    // `color: 'text.inverse'` already resolve to the correct Zimmermann value. House style
    87	    // instead: use var(--zimm-scale-*) / var(--zimm-color-*) so every call site is an
    88	    // unambiguous zimm reference, not something a reviewer has to check against theme/index.ts's
    89	    // registered-scale list to know whether it's correct.
    90	    expect(offenders).toEqual([]);
    91	  });
    92	
    93	  test('no recipe silently inherits a base SFCC recipe of the same name', () => {
    94	    // extendTheme DEEP MERGES. These three intentionally share a base key: Button wants the
    95	    // base variants, and Header/ListMenu are partial overrides of components whose other
    96	    // parts we still rely on. Anything else must be namespaced (e.g. ZimmFooter, not Footer).
    97	    const INTENTIONAL_MERGES = ['Button', 'Header', 'ListMenu'];
    98	
    99	    const unexpected = Object.keys(components)
   100	      .filter((name) => !INTENTIONAL_MERGES.includes(name))
   101	      .filter((name) => {
   102	        const ours = resolveBaseStyle(components[name as keyof typeof components] as never) ?? {};
   103	        const merged = resolveBaseStyle((theme.components?.[name] ?? {}) as Record<string, unknown>) ?? {};
   104	        const ourKeys = new Set(Object.keys(ours as object));
   105	        // A key present after composition that we never declared came from the base theme.
   106	        return Object.keys(merged as object).some((k) => !ourKeys.has(k));
   107	      });
   108	
   109	    expect(unexpected).toEqual([]);
   110	  });
   111	});

